import{FilterInput,SelectFilterInput,AssignedEntityFilterInput,DateFilterInput,TextFilterInput}from"/js/dist/filterInputs.min.js";import{container}from"/js/dist/simpleDIContainer.min.js";export default class FilterFormManager{constructor(){this.filters=[],this.inputs=[],this.apiService=container.resolve("apiService")}collect(){return this.filters=[],this.inputs=[],document.querySelectorAll('select[id^="advancedSearch_"]').forEach((e=>{"advancedSearch_assigned_to"===e.id?this.inputs.push(new AssignedEntityFilterInput(e,this.apiService)):this.inputs.push(new SelectFilterInput(e,this.apiService))})),document.querySelectorAll('input[id^="advancedSearch_"][id$="_start"][type="date"], input[id^="advancedSearch_"][id$="_end"][type="date"]').forEach((e=>{this.inputs.push(new DateFilterInput(e,this.apiService))})),document.querySelectorAll('input[id^="advancedSearch_"][type="text"]').forEach((e=>{this.inputs.push(new TextFilterInput(e,this.apiService))})),this.inputs.forEach((e=>{e.appendTo(this.filters)})),this.filters}clearAll(){this.collect(),this.inputs.forEach((e=>{e.clear()}))}async setValuesFromResponse(e){this.clearAll();const t=[];for(const i of e){const{field:e,value:s}=i,n=this.inputs.find((t=>t.key===e));if(n)try{const e=n.setValue(s);e instanceof Promise&&t.push(e)}catch(t){console.error(`Failed to set value for "${e}":`,t)}else console.warn(`No input found for key: ${e}`)}await Promise.all(t),this.setAdvancedSearchPanelFilterEnabledState(!1)}setAdvancedSearchPanelFilterEnabledState(e){const t=document.getElementById("advancedSearchPanel").getElementsByTagName("*");for(let i=0;i<t.length;i++)t[i].disabled=e}}
